export const PWA_SW_SCRIPT = "const CACHE_NAME = \"pigeon-cache-v1\";\n\nself.addEventListener(\"install\", (event) => {\n  self.skipWaiting();\n});\n\nself.addEventListener(\"activate\", (event) => {\n  event.waitUntil(\n    caches.keys().then((keys) =>\n      Promise.all(\n        keys.map((k) => {\n          if (k !== CACHE_NAME) return caches.delete(k);\n        })\n      )\n    ).then(() => self.clients.claim())\n  );\n});\n\nself.addEventListener(\"fetch\", (event) => {\n  const url = new URL(event.request.url);\n\n  // Bypass WebSocket and API requests\n  if (url.pathname.startsWith(\"/ws\") || url.pathname.startsWith(\"/api/\")) {\n    return;\n  }\n\n  // Network-First for Navigation / HTML documents:\n  // Always fetch latest server code first; fallback to cache if offline\n  if (event.request.mode === \"navigate\" || event.request.destination === \"document\") {\n    event.respondWith(\n      fetch(event.request)\n        .then((response) => {\n          if (response && response.status === 200) {\n            const copy = response.clone();\n            caches.open(CACHE_NAME).then((cache) => cache.put(event.request, copy));\n          }\n          return response;\n        })\n        .catch(() => caches.match(event.request).then((res) => res || caches.match(\"/\")))\n    );\n    return;\n  }\n\n  // Stale-While-Revalidate for icons and static assets\n  event.respondWith(\n    caches.match(event.request).then((cached) => {\n      const networked = fetch(event.request)\n        .then((response) => {\n          if (response && response.status === 200) {\n            const copy = response.clone();\n            caches.open(CACHE_NAME).then((cache) => cache.put(event.request, copy));\n          }\n          return response;\n        })\n        .catch(() => cached);\n      return cached || networked;\n    })\n  );\n});\n";

